changeSet.sql:
SET QUOTED_IDENTIFIER ON; DECLARE @Now DATETIME2 = SYSUTCDATETIME();
UPDATE pf SET pf.[Enabled] = 1, pf.UpdatedAt = @Now FROM app.PlanFeatures pf INNER JOIN app.Plans p ON p.Id = pf.PlanId WHERE pf.FeatureCode = N'GYM_CHAT' AND p.Code IN (N'BUSINESS_FREE', N'BASIC', N'PRO', N'ENTERPRISE') AND pf.[Enabled] = 0;
INSERT INTO app.PlanFeatures (Id, PlanId, FeatureCode, [Enabled], CreatedAt, UpdatedAt) SELECT NEWID(), p.Id, N'GYM_CHAT', 1, @Now, @Now FROM app.Plans p WHERE p.Code IN (N'BUSINESS_FREE', N'BASIC', N'PRO', N'ENTERPRISE') AND NOT EXISTS ( SELECT 1 FROM app.PlanFeatures existing WHERE existing.PlanId = p.Id AND existing.FeatureCode = N'GYM_CHAT');
